# Extract user/assistant intents from Sep 19-21 transcripts briefly
python3 - <<'PY'
import json, os
from pathlib import Path
roots = [
 Path("/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts"),
 Path.home()/".dc-platform/memory/mirrors/agent-transcripts",
]
# also memory mirrors
for host in ["old-mac","new-mac"]:
  p = Path.home()/f".dc-platform/memory/mirrors/agent-transcripts/{host}"
  if p.exists():
    roots.append(p)

seen=set()
for root in roots:
  if not root.exists(): continue
  for jf in root.rglob("*.jsonl"):
    try:
      mtime=jf.stat().st_mtime
    except: continue
    # Sep 19-21 window roughly
    import datetime
    from datetime import timezone, timedelta
    TZ=timezone(timedelta(hours=8))
    dt=datetime.datetime.fromtimestamp(mtime, TZ)
    if dt.date().isoformat() < "2026-09-19":
      continue
    key=str(jf)
    if key in seen: continue
    seen.add(key)
    users=[]
    with open(jf, encoding='utf-8', errors='replace') as f:
      for line in f:
        try: o=json.loads(line)
        except: continue
        role=o.get("role") or o.get("type") or ""
        # various formats
        msg=o.get("message") or o
        if isinstance(msg, dict):
          role = role or msg.get("role","")
          content=msg.get("content")
        else:
          content=o.get("content") or o.get("text")
        text=""
        if isinstance(content, list):
          for c in content:
            if isinstance(c, dict) and c.get("type") in ("text","input_text"):
              text += c.get("text","")
            elif isinstance(c, str):
              text += c
        elif isinstance(content, str):
          text=content
        if role in ("user","human") and text.strip():
          users.append(text.strip().replace("\n"," ")[:160])
    if users:
      print(f"\n## {dt.date()} {jf.parent.name[:8]}… ({len(users)} user msgs)")
      for u in users[:8]:
        print("-", u)
PY
